import numpy as np
from boot.influence import empinf

city = {
    "u": np.array([138, 93, 61, 179, 48, 37, 29, 23, 30, 2], dtype=float),
    "x": np.array([143, 104, 69, 260, 75, 63, 50, 48, 111, 50], dtype=float),
}

def ratio(d, w):
    return np.sum(d["x"] * w) / np.sum(d["u"] * w)

print(empinf(data=city, statistic=ratio))
print(empinf(data=city, statistic=ratio, type="jack"))
print(empinf(data=city, statistic=ratio, type="pos"))
